@Service
public class OrderFacade {                 // coarse-grained business-tier entry point
    private final PricingService pricing; private final InventoryService inv; private final OrderRepository repo;
    OrderFacade(PricingService p, InventoryService i, OrderRepository r) { pricing = p; inv = i; repo = r; }

    @Transactional                          // one unit of work for the whole use case
    public OrderId placeOrder(PlaceOrderRequest req) {
        var quote = pricing.quote(req.sku(), req.qty());
        inv.reserve(req.sku(), req.qty());
        return repo.insert(new Order(req.customerId(), quote));
    }
}

