@Stateless
public class OrderFacadeBean implements OrderFacade {   // coarse business interface
    @PersistenceContext EntityManager em;
    @EJB PricingService pricing; @EJB InventoryService inv;
    @Override public OrderId placeOrder(PlaceOrderRequest req) {  // container-managed tx
        var quote = pricing.quote(req.sku(), req.qty());
        inv.reserve(req.sku(), req.qty());
        var order = new Order(req.customerId(), quote);
        em.persist(order);
        return order.getId();
    }
}
